// the API put them: a named list ({"spaces": [...]}) or items/data/results, and
// a cursor at the top level or inside a page/pagination/pageInfo/meta envelope.
func decodePage[T any](raw []byte, itemsKey string) ([]T, string, error) {
	var items []T
	if bytes.HasPrefix(bytes.TrimSpace(raw), []byte("[")) {
		err := json.Unmarshal(raw, &items)
		return items, "", err
	}
	var top map[string]json.RawMessage
	if err := json.Unmarshal(raw, &top); err != nil {
		return nil, "", err
	}
	keys := []string{itemsKey, "items", "data", "results"}
	found := false
	for _, k := range keys {
		if v, ok := top[k]; ok && k != "" && bytes.HasPrefix(bytes.TrimSpace(v), []byte("[")) {
			if err := json.Unmarshal(v, &items); err != nil {
				return nil, "", err
			}
			found = true
			break
		}
	}
	if !found {
		var lists []json.RawMessage
		for _, v := range top {
			if bytes.HasPrefix(bytes.TrimSpace(v), []byte("[")) {
				lists = append(lists, v)
			}
		}
		if len(lists) == 1 {
			if err := json.Unmarshal(lists[0], &items); err != nil {
				return nil, "", err
			}
		}
	}
	return items, cursorOf(top), nil
}

func cursorOf(top map[string]json.RawMessage) string {
	holders := []map[string]json.RawMessage{top}
	for _, k := range []string{"page", "pagination", "pageInfo", "meta"} {
		var m map[string]json.RawMessage
		if v, ok := top[k]; ok && json.Unmarshal(v, &m) == nil {
			holders = append(holders, m)
		}
	}
	for _, h := range holders {
		for _, k := range []string{"hasMore", "hasNextPage"} {
			if string(h[k]) == "false" {
				return ""
			}
		}
		for _, k := range []string{"nextCursor", "endCursor", "next_cursor", "cursor"} {
			var s string
			if v, ok := h[k]; ok && json.Unmarshal(v, &s) == nil && s != "" {
				return s
			}
		}
	}
	return ""
}

// stream opens a server-sent-event stream and calls handler with each event's data.
func (c *Client) stream(ctx context.Context, method, path string, query url.Values, body any, opts []RequestOption, handler func(json.RawMessage) error) error {
	var payload []byte
	if body != nil {
		b, err := json.Marshal(body)
		if err != nil {
			return err
		}
		payload = b
	}
	req, err := c.newRequest(ctx, method, path, query, payload, opts)
	if err != nil {
		return err
	}
	req.Header.Set("Accept", "text/event-stream")
	res, err := c.HTTPClient.Do(req)
	if err != nil {
		return err
	}
	defer res.Body.Close()
	if res.StatusCode >= 400 {
		raw, _ := io.ReadAll(res.Body)
		return newError(res, raw)
	}
	scanner := bufio.NewScanner(res.Body)
	scanner.Buffer(make([]byte, 64*1024), 4*1024*1024)
	var data []string
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			if len(data) > 0 {
				if err := handler(json.RawMessage(strings.Join(data, "\n"))); err != nil {
					return err
				}
				data = nil
			}
			continue
		}
		if strings.HasPrefix(line, "data:") {
			data = append(data, strings.TrimSpace(line[5:]))
		}
	}
	return scanner.Err()
}

// String returns a pointer to v, for optional fields.
func String(v string) *string { return &v }

// Int returns a pointer to v, for optional integer fields.
func Int(v int64) *int64 { return &v }

// Float returns a pointer to v, for optional number fields.
func Float(v float64) *float64 { return &v }

// Bool returns a pointer to v, for optional boolean fields.
func Bool(v bool) *bool { return &v }
